import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.BrO6lPIi.js";const b=JSON.parse('{"title":"消息通信机制","description":"本文面向 Chrome Extension（Manifest V3，版本 2.3.1）与独立本地 Agent（Node.js，版本 2.3.1）的双进程架构，系统性说明以下能力：。","frontmatter":{"title":"消息通信机制","description":"本文面向 Chrome Extension（Manifest V3，版本 2.3.1）与独立本地 Agent（Node.js，版本 2.3.1）的双进程架构，系统性说明以下能力：。"},"headers":[],"relativePath":"API-参考文档/Chrome-Extension-API/消息通信机制/index.md","filePath":"API-参考文档/Chrome-Extension-API/消息通信机制/index.md","lastUpdated":null}'),o={name:"API-参考文档/Chrome-Extension-API/消息通信机制/index.md"};function i(l,e,c,s,d,g){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="消息通信机制" tabindex="-1">消息通信机制 <a class="header-anchor" href="#消息通信机制" aria-label="Permalink to &quot;消息通信机制&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js" target="_blank" rel="noreferrer">src/content/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/utils.js" target="_blank" rel="noreferrer">src/shared/utils.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js" target="_blank" rel="noreferrer">src/background/local-agent-client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/schedule-panel.js" target="_blank" rel="noreferrer">src/side_panel/schedule-panel.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/index.js" target="_blank" rel="noreferrer">src/options/index.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与通信边界">项目结构与通信边界</a></li><li><a href="#chrome-扩展消息模型sendmessage-与-onmessage">Chrome 扩展消息模型：sendMessage 与 onMessage</a></li><li><a href="#content-script-到-background-service-worker-的消息路由表">Content Script 到 Background Service Worker 的消息路由表</a></li><li><a href="#扩展端与-agent-端的-httpwebsocket-通信契约">扩展端与 Agent 端的 HTTP/WebSocket 通信契约</a></li><li><a href="#从网页脚本调用后台功能的端到端流程">从网页脚本调用后台功能的端到端流程</a></li><li><a href="#超时重试与连接状态管理">超时、重试与连接状态管理</a></li><li><a href="#架构总览图">架构总览图</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文面向 Chrome Extension（Manifest V3，版本 2.3.1）与独立本地 Agent（Node.js，版本 2.3.1）的双进程架构，系统性说明以下能力：</p><ul><li><code>chrome.runtime.sendMessage</code> 与 <code>chrome.runtime.onMessage</code> 的同步/异步使用方式。</li><li>Content Script 中基于 Map 的消息路由表结构及 O(1) 分发逻辑。</li><li>Background Service Worker 作为扩展内部消息中枢的职责。</li><li>扩展端通过 <code>local-agent-client.js</code> 与 Agent 端 <code>server.js</code> 之间的 HTTP 与 WebSocket 契约。</li><li>消息超时、可达性缓存、SW 保活、Agent 重启等运行时约束。</li><li>实际代码路径引用，便于读者直接定位实现。</li></ul><p>本项目是双进程架构：Chrome 扩展端位于 <code>src/</code>，Agent 端入口为 <code>agent/src/server.js</code>。两端版本号保持同步，文档以 2.3.1 为准。Agent 源码修改后必须重启进程，新接口才生效。</p><h2 id="项目结构与通信边界" tabindex="-1">项目结构与通信边界 <a class="header-anchor" href="#项目结构与通信边界" aria-label="Permalink to &quot;项目结构与通信边界&quot;">​</a></h2><p>扩展端按 MV3 Service Worker 组织，核心通信边界如下：</p><ul><li><strong>网页脚本 / Content Script</strong>：运行在页面上下文中，负责 DOM 操作、页面信息提取、用户交互。</li><li><strong>Background Service Worker</strong>：扩展全局上下文，负责消息路由、工具调度、Agent 客户端封装、侧边栏控制、定时任务等。</li><li><strong>Side Panel / Options / Offscreen</strong>：扩展 UI 层，通过 <code>chrome.runtime.sendMessage</code> 与 Background 通信。</li><li><strong>Agent 服务</strong>：独立 Node.js 进程，提供文件系统、命令执行、Skill、MCP、RAG 等能力，暴露 HTTP API 与 WebSocket。</li></ul><pre class="mermaid">graph TB
WebPage[&quot;网页脚本&quot;] --&gt; ContentScript[&quot;Content Script&lt;br/&gt;src/content/index.js&quot;]
ContentScript --&gt; Background[&quot;Background Service Worker&lt;br/&gt;src/background/index.js&quot;]
SidePanel[&quot;Side Panel / Options&quot;] --&gt; Background
Background --&gt; AgentClient[&quot;Agent 客户端&lt;br/&gt;src/background/local-agent-client.js&quot;]
AgentClient --&gt; AgentServer[&quot;Agent 服务端&lt;br/&gt;agent/src/server.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L920-L1844" target="_blank" rel="noreferrer">src/background/index.js#L920-L1844</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L553" target="_blank" rel="noreferrer">agent/src/server.js#L417-L553</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L65" target="_blank" rel="noreferrer">agent/src/server.js#L1-L65</a></li></ul><h2 id="chrome-扩展消息模型-sendmessage-与-onmessage" tabindex="-1">Chrome 扩展消息模型：sendMessage 与 onMessage <a class="header-anchor" href="#chrome-扩展消息模型-sendmessage-与-onmessage" aria-label="Permalink to &quot;Chrome 扩展消息模型：sendMessage 与 onMessage&quot;">​</a></h2><h3 id="同步消息" tabindex="-1">同步消息 <a class="header-anchor" href="#同步消息" aria-label="Permalink to &quot;同步消息&quot;">​</a></h3><p>当接收方在 <code>onMessage</code> 处理器中直接调用 <code>sendResponse(result)</code> 并返回 <code>undefined</code> 时，发送方的回调立即拿到结果。适用于轻量、无网络 IO 的操作。</p><p>示例路径：</p><ul><li>Content Script 同步处理简单查询类消息。</li><li>Background 向 Side Panel 或 Options 广播状态变更。</li></ul><p>参考实现位置：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/utils.js#L74-L78" target="_blank" rel="noreferrer">src/shared/utils.js#L74-L78</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/schedule-panel.js#L134-L136" target="_blank" rel="noreferrer">src/side_panel/schedule-panel.js#L134-L136</a></li></ul><h3 id="异步消息" tabindex="-1">异步消息 <a class="header-anchor" href="#异步消息" aria-label="Permalink to &quot;异步消息&quot;">​</a></h3><p>当处理器返回 <code>true</code>，或通过 Promise 调用 <code>sendResponse</code>，表示消息通道保持开放，后续再回复。适用于：</p><ul><li>需要等待 DOM 操作完成。</li><li>需要等待网络请求或子任务完成。</li><li>需要维持长连接（如 keepalive port）。</li></ul><p>参考实现位置：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L210-L246" target="_blank" rel="noreferrer">src/content/index.js#L210-L246</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li></ul><h3 id="关键行为总结" tabindex="-1">关键行为总结 <a class="header-anchor" href="#关键行为总结" aria-label="Permalink to &quot;关键行为总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>发送方</th><th>接收方</th><th>返回值约定</th></tr></thead><tbody><tr><td>轻量同步响应</td><td><code>chrome.runtime.sendMessage(msg, cb)</code></td><td><code>onMessage</code> 中直接 <code>sendResponse(data)</code></td><td>同步返回</td></tr><tr><td>异步响应</td><td><code>chrome.runtime.sendMessage(msg, cb)</code></td><td><code>onMessage</code> 中 <code>Promise.then(sendResponse)</code> 并返回 <code>true</code></td><td>延迟回复</td></tr><tr><td>长连接</td><td><code>chrome.runtime.connect(portName)</code></td><td><code>onConnect</code> 监听端口</td><td>双向 <code>postMessage</code></td></tr><tr><td>跨 Tab 定向</td><td><code>chrome.tabs.sendMessage(tabId, msg)</code></td><td>目标 Tab 的 Content Script <code>onMessage</code></td><td>同 sendMessage</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/utils.js#L62-L78" target="_blank" rel="noreferrer">src/shared/utils.js#L62-L78</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L209-L247" target="_blank" rel="noreferrer">src/content/index.js#L209-L247</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li></ul><h2 id="content-script-到-background-service-worker-的消息路由表" tabindex="-1">Content Script 到 Background Service Worker 的消息路由表 <a class="header-anchor" href="#content-script-到-background-service-worker-的消息路由表" aria-label="Permalink to &quot;Content Script 到 Background Service Worker 的消息路由表&quot;">​</a></h2><p>Content Script 使用一个集中式 <code>HANDLERS</code> Map，将 <code>message.type</code> 映射到具体处理器函数。该设计具备以下特点：</p><ul><li><strong>O(1) 查找</strong>：通过对象键直接定位处理器。</li><li><strong>分类清晰</strong>：页面读取、页面交互、表单输入、信息提取、媒体输出、异步工具等分组明确。</li><li><strong>异步标记集合</strong>：<code>ASYNC_HANDLERS</code> 声明哪些类型需要保持消息通道开放。</li><li><strong>顶层帧限制</strong>：<code>TOP_FRAME_ONLY_TYPES</code> 避免 iframe 抢占响应。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;收到 chrome.runtime.onMessage&quot;] --&gt; CheckTop[&quot;是否 TOP_FRAME_ONLY 且非顶层帧？&quot;]
CheckTop --&gt; |是| Ignore[&quot;忽略消息&quot;]
CheckTop --&gt; |否| Lookup[&quot;HANDLERS[message.type]&quot;]
Lookup --&gt; Found{&quot;找到处理器？&quot;}
Found --&gt; |否| Exit[&quot;不处理&quot;]
Found --&gt; |是| CallHandler[&quot;调用 handler(message)&quot;]
CallHandler --&gt; AsyncCheck{&quot;是否 ASYNC_HANDLERS 或返回 Promise？&quot;}
AsyncCheck --&gt; |是| KeepOpen[&quot;return true&lt;br/&gt;Promise.then(sendResponse)&quot;]
AsyncCheck --&gt; |否| SyncReply[&quot;sendResponse(result)&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L195-L247" target="_blank" rel="noreferrer">src/content/index.js#L195-L247</a></li></ul><h3 id="路由表分类摘要" tabindex="-1">路由表分类摘要 <a class="header-anchor" href="#路由表分类摘要" aria-label="Permalink to &quot;路由表分类摘要&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>典型 message.type</th><th>职责</th></tr></thead><tbody><tr><td>页面读取</td><td><code>GET_PAGE_TEXT</code>、<code>GET_FULL_HTML</code>、<code>QUERY_ELEMENTS</code>、<code>GET_SELECTED_CONTENT</code></td><td>获取文本、HTML、可交互元素、选区内容</td></tr><tr><td>页面交互</td><td><code>INTERACT_ELEMENT</code>、<code>FILL_FORM</code>、<code>SCROLL_TO</code></td><td>点击、填表、滚动</td></tr><tr><td>表单输入</td><td><code>KEYBOARD_INPUT</code>、<code>FILE_UPLOAD</code></td><td>键盘输入、文件上传</td></tr><tr><td>信息提取</td><td><code>EXTRACT_TABLE</code>、<code>EXTRACT_METADATA</code>、<code>EXTRACT_LINKS</code>、<code>EXTRACT_FORMS</code>、<code>EXTRACT_IMAGES</code>、<code>SEARCH_IN_PAGE</code>、<code>IFRAME_CONTENT</code>、<code>SCROLL_COLLECT</code></td><td>结构化数据抽取</td></tr><tr><td>媒体输出</td><td><code>MANAGE_STORAGE</code>、<code>INJECT_CSS</code></td><td>存储管理与样式注入</td></tr><tr><td>异步工具</td><td><code>COPY_TO_CLIPBOARD</code>、<code>PASTE_FROM_CLIPBOARD</code>、<code>WAIT_ELEMENT</code>、<code>SELECT_DROPDOWN</code>、<code>QRCODE</code>、<code>START_REGION_SELECTION</code></td><td>需要等待或 UI 交互的工具</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L195-L247" target="_blank" rel="noreferrer">src/content/index.js#L195-L247</a></li></ul><h2 id="扩展端与-agent-端的-http-websocket-通信契约" tabindex="-1">扩展端与 Agent 端的 HTTP/WebSocket 通信契约 <a class="header-anchor" href="#扩展端与-agent-端的-http-websocket-通信契约" aria-label="Permalink to &quot;扩展端与 Agent 端的 HTTP/WebSocket 通信契约&quot;">​</a></h2><h3 id="总体契约" tabindex="-1">总体契约 <a class="header-anchor" href="#总体契约" aria-label="Permalink to &quot;总体契约&quot;">​</a></h3><p>扩展端通过 <code>local-agent-client.js</code> 统一封装对 Agent 的 HTTP 与 WebSocket 调用；Agent 端由 <code>server.js</code> 提供 HTTP Router 与 WebSocket 支持。所有需认证的请求携带 <code>Authorization: Bearer &lt;token&gt;</code>。</p><pre class="mermaid">sequenceDiagram
participant BG as &quot;Background Service Worker&quot;
participant Client as &quot;local-agent-client.js&quot;
participant Agent as &quot;agent/src/server.js&quot;
BG-&gt;&gt;Client : 调用 execCommand / readFile / getMcpTools 等
Client-&gt;&gt;Client : agentRequest(path, body, method, timeoutMs)
Client-&gt;&gt;Agent : fetch(url, { Authorization : Bearer token })
Agent--&gt;&gt;Client : JSON { success, ... }
Client--&gt;&gt;BG : 返回结果或错误
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L553" target="_blank" rel="noreferrer">agent/src/server.js#L417-L553</a></li></ul><h3 id="http-端点分类" tabindex="-1">HTTP 端点分类 <a class="header-anchor" href="#http-端点分类" aria-label="Permalink to &quot;HTTP 端点分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>领域</th><th>端点</th><th>方法</th><th>说明</th></tr></thead><tbody><tr><td>配对与会话</td><td><code>/api/pair</code></td><td>POST</td><td>扩展与 Agent 配对，返回 token</td></tr><tr><td>健康检查</td><td><code>/api/status</code></td><td>GET</td><td>返回版本、平台、RAG 可用性等</td></tr><tr><td>详细状态</td><td><code>/api/status/detail</code></td><td>GET</td><td>工作目录、资源使用、进程列表等</td></tr><tr><td>文件系统</td><td><code>/api/fs/read</code>、<code>/api/fs/write</code>、<code>/api/fs/list</code>、<code>/api/fs/delete</code>、<code>/api/fs/search_files</code>、<code>/api/fs/search_content</code></td><td>POST</td><td>文件读写、目录浏览、搜索</td></tr><tr><td>文件上传</td><td><code>/api/files/upload</code></td><td>POST</td><td>multipart/form-data 上传</td></tr><tr><td>命令执行</td><td><code>/api/exec</code></td><td>POST</td><td>启动命令，支持 wait、timeoutMs</td></tr><tr><td>命令停止</td><td><code>/api/exec/stop</code></td><td>POST</td><td>停止运行中的命令</td></tr><tr><td>MCP</td><td><code>/api/mcp/tools</code>、<code>/api/mcp/call</code>、<code>/api/mcp/servers/*</code></td><td>GET/POST/DELETE/PUT</td><td>MCP 工具与服务端管理</td></tr><tr><td>Skill</td><td><code>/api/skill/*</code></td><td>GET/POST/DELETE</td><td>Skill 列表、详情、执行、导入、启用/禁用</td></tr><tr><td>Agent 管理</td><td><code>/api/agent/restart</code>、<code>/api/agent/update</code>、<code>/api/shutdown</code></td><td>POST</td><td>重启、更新、关闭</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L43-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L43-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L749" target="_blank" rel="noreferrer">agent/src/server.js#L471-L749</a></li></ul><h3 id="websocket-契约" tabindex="-1">WebSocket 契约 <a class="header-anchor" href="#websocket-契约" aria-label="Permalink to &quot;WebSocket 契约&quot;">​</a></h3><p>WebSocket 用于命令执行的实时输出流。扩展端通过 <code>createExecWebSocket(wsUrl, onMessage, onClose, onError)</code> 建立连接，Token 通过 URL 参数附加。</p><p>关键点：</p><ul><li>Token 从当前活跃 Agent 配置中获取。</li><li>若 Agent 已知不可达，直接走错误回调，避免无效连接。</li><li>空闲超时由调用方统一管理，避免双重超时冲突。</li><li>连接成功 resolve WebSocket 实例，失败 reject 并触发 onError。</li></ul><pre class="mermaid">sequenceDiagram
participant Executor as &quot;tool-executor.js&quot;
participant Client as &quot;local-agent-client.js&quot;
participant WS as &quot;WebSocket&quot;
participant Agent as &quot;agent/src/server.js&quot;
Executor-&gt;&gt;Client : createExecWebSocket(wsUrl, onMessage, onClose, onError)
Client-&gt;&gt;Client : 校验 connected 与 reachability
Client-&gt;&gt;WS : new WebSocket(authenticatedUrl)
WS--&gt;&gt;Client : onopen → resolve(ws)
WS--&gt;&gt;Executor : onmessage(JSON)
WS--&gt;&gt;Executor : onclose → onClose()
WS--&gt;&gt;Executor : onerror → onError(error)
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li></ul><h3 id="认证与安全" tabindex="-1">认证与安全 <a class="header-anchor" href="#认证与安全" aria-label="Permalink to &quot;认证与安全&quot;">​</a></h3><ul><li>Agent 端对大多数接口要求 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>CORS 仅放行 <code>chrome-extension://</code> 来源。</li><li>配对接口 <code>/api/pair</code> 无需认证，但会记录 extensionId。</li><li>心跳接口 <code>/api/heartbeat</code> 刷新在线状态，不返回敏感信息。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L235-L266" target="_blank" rel="noreferrer">agent/src/server.js#L235-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L553" target="_blank" rel="noreferrer">agent/src/server.js#L471-L553</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li></ul><h2 id="从网页脚本调用后台功能的端到端流程" tabindex="-1">从网页脚本调用后台功能的端到端流程 <a class="header-anchor" href="#从网页脚本调用后台功能的端到端流程" aria-label="Permalink to &quot;从网页脚本调用后台功能的端到端流程&quot;">​</a></h2><p>以“从网页截图”为例，展示完整链路：</p><pre class="mermaid">sequenceDiagram
participant Page as &quot;网页脚本&quot;
participant Content as &quot;Content Script&quot;
participant BG as &quot;Background Service Worker&quot;
participant Panel as &quot;Side Panel&quot;
Page-&gt;&gt;Content : 快捷键触发 CAPTURE_TAB_FROM_PAGE
Content-&gt;&gt;BG : chrome.runtime.sendMessage({ type : &#39;CAPTURE_TAB_FROM_PAGE&#39; })
BG-&gt;&gt;BG : 执行截图逻辑
BG--&gt;&gt;Panel : chrome.runtime.sendMessage({ type : &#39;SCREENSHOT_RESULT&#39;, dataUrl, mode })
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L54-L72" target="_blank" rel="noreferrer">src/content/index.js#L54-L72</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1306-L1325" target="_blank" rel="noreferrer">src/background/index.js#L1306-L1325</a></li></ul><p>另一个常见流程是“选项页通知 Background 打开/关闭”：</p><pre class="mermaid">sequenceDiagram
participant Options as &quot;Options 页面&quot;
participant BG as &quot;Background Service Worker&quot;
Options-&gt;&gt;BG : chrome.runtime.sendMessage({ type : &#39;OPTIONS_PAGE_OPEN&#39; })
BG-&gt;&gt;BG : 设置 _optionsPageOpen = true
BG--&gt;&gt;Options : 可选状态广播
Options-&gt;&gt;BG : chrome.runtime.sendMessage({ type : &#39;OPTIONS_PAGE_CLOSED&#39; })
BG-&gt;&gt;BG : 设置 _optionsPageOpen = false
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/index.js#L2174-L2192" target="_blank" rel="noreferrer">src/options/index.js#L2174-L2192</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1823-L1832" target="_blank" rel="noreferrer">src/background/index.js#L1823-L1832</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L54-L72" target="_blank" rel="noreferrer">src/content/index.js#L54-L72</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1306-L1325" target="_blank" rel="noreferrer">src/background/index.js#L1306-L1325</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/index.js#L2174-L2192" target="_blank" rel="noreferrer">src/options/index.js#L2174-L2192</a></li></ul><h2 id="超时、重试与连接状态管理" tabindex="-1">超时、重试与连接状态管理 <a class="header-anchor" href="#超时、重试与连接状态管理" aria-label="Permalink to &quot;超时、重试与连接状态管理&quot;">​</a></h2><h3 id="消息超时" tabindex="-1">消息超时 <a class="header-anchor" href="#消息超时" aria-label="Permalink to &quot;消息超时&quot;">​</a></h3><ul><li>HTTP 请求通过 <code>AbortController</code> 实现超时，默认 60 秒，部分接口（如下载）延长至 120 秒。</li><li>WebSocket 空闲超时由调用方统一管理，避免与连接层双重超时冲突。</li></ul><p>参考实现位置：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L410-L442" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L410-L442</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li></ul><h3 id="重试机制" tabindex="-1">重试机制 <a class="header-anchor" href="#重试机制" aria-label="Permalink to &quot;重试机制&quot;">​</a></h3><ul><li>代码未实现自动重试循环，而是通过可达性缓存快速失败，避免阻塞。</li><li>用户可通过“触发健康检查”手动刷新状态。</li></ul><p>参考实现位置：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L405-L408" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L405-L408</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1817-L1822" target="_blank" rel="noreferrer">src/background/index.js#L1817-L1822</a></li></ul><h3 id="连接状态管理" tabindex="-1">连接状态管理 <a class="header-anchor" href="#连接状态管理" aria-label="Permalink to &quot;连接状态管理&quot;">​</a></h3><ul><li>Background 维护 <code>_agentReachability</code> 内存缓存，按 agentId 区分可达性。</li><li>SW 保活通过 side panel 的 keepalive port 防止被系统回收。</li><li>Agent 重启/更新后需重新配对或刷新 token。</li></ul><p>参考实现位置：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L101-L127" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L101-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L405-L442" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L405-L442</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li></ul><h2 id="架构总览图" tabindex="-1">架构总览图 <a class="header-anchor" href="#架构总览图" aria-label="Permalink to &quot;架构总览图&quot;">​</a></h2><pre class="mermaid">classDiagram
class ContentScript {
+HANDLERS Map
+ASYNC_HANDLERS Set
+TOP_FRAME_ONLY_TYPES Set
+onMessage(message, sender, sendResponse)
}
class BackgroundServiceWorker {
+onMessage(message, sender, sendResponse)
+keepalivePort(sessionId)
+sidePanelControl()
+agentHealthCheck()
}
class LocalAgentClient {
+agentRequest(path, body, method, timeoutMs)
+agentGet(path, timeoutMs)
+createExecWebSocket(wsUrl, onMessage, onClose, onError)
+getAgentConfig()
}
class AgentServer {
+httpServer(req, res)
+wsServer(connection)
+authMiddleware(token)
+corsFilter(origin)
}
ContentScript --&gt; BackgroundServiceWorker : &quot;chrome.runtime.sendMessage&quot;
BackgroundServiceWorker --&gt; LocalAgentClient : &quot;HTTP/WebSocket&quot;
LocalAgentClient --&gt; AgentServer : &quot;fetch + WebSocket&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L74-L193" target="_blank" rel="noreferrer">src/content/index.js#L74-L193</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L920-L1844" target="_blank" rel="noreferrer">src/background/index.js#L920-L1844</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L749" target="_blank" rel="noreferrer">agent/src/server.js#L417-L749</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>可能原因</th><th>排查建议</th></tr></thead><tbody><tr><td>Content Script 消息无响应</td><td>非顶层帧拦截、handler 未注册、异步未 return true</td><td>检查 <code>TOP_FRAME_ONLY_TYPES</code> 与 <code>ASYNC_HANDLERS</code></td></tr><tr><td>Background 被系统回收</td><td>SW 空闲终止、无 keepalive</td><td>确认 side panel 保活连接存在</td></tr><tr><td>Agent 请求超时</td><td>网络不可达、Agent 未启动、token 失效</td><td>检查 <code>/api/status</code> 与 <code>Authorization</code> 头</td></tr><tr><td>WebSocket 连接失败</td><td>Agent 重启、token 过期、地址替换异常</td><td>查看 <code>createExecWebSocket</code> 日志与 reachable 缓存</td></tr><tr><td>大消息截断</td><td><code>chrome.runtime.sendMessage</code> 单条最大 64MiB</td><td>使用日志截断逻辑或分片传输</td></tr></tbody></table><h3 id="关键日志位置" tabindex="-1">关键日志位置 <a class="header-anchor" href="#关键日志位置" aria-label="Permalink to &quot;关键日志位置&quot;">​</a></h3><ul><li>Background：<code>[Background]</code> 前缀日志。</li><li>Agent：<code>[Agent]</code> 前缀日志。</li><li>AgentClient：<code>[AgentClient]</code> 前缀日志。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/index.js#L209-L247" target="_blank" rel="noreferrer">src/content/index.js#L209-L247</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L405-L442" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L405-L442</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L425" target="_blank" rel="noreferrer">agent/src/server.js#L417-L425</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本项目的消息通信机制围绕三层展开：</p><ol><li><strong>扩展内部</strong>：Content Script 通过集中式路由表与 Background Service Worker 通信，支持同步与异步模式。</li><li><strong>扩展与 Agent</strong>：Background 通过 <code>local-agent-client.js</code> 封装 HTTP 与 WebSocket，统一认证、超时与可达性管理。</li><li><strong>Agent 服务端</strong>：提供 RESTful API 与实时命令输出流，支持文件、命令、Skill、MCP、RAG 等能力。</li></ol><p>在实际使用中，应重点关注：</p><ul><li>消息类型定义与路由一致性。</li><li>异步处理器正确返回 <code>true</code> 或使用 Promise。</li><li>Agent 连接状态与 token 有效性。</li><li>SW 生命周期与保活机制。</li><li>大消息截断与性能优化。</li></ul>`,105)])])}const u=t(o,[["render",i]]);export{b as __pageData,u as default};
